      "path": ".github/workflows/catalog-sync.yml",
      "content": "# Pushes catalog/plugins/*.json and the catalog/categories.json list to the\n# production Worker (POST /api/v1/catalog/sync) and refreshes the README\n# projections from the live catalog API. Categories travel as data in that request,\n# so a category change ships from this repository without a Worker redeploy.\n#\n# It also owns the `assets` branch, which holds nothing but the README hero\n# screenshot (homepage.png). That branch is never merged and has no history worth\n# keeping: each refresh force-pushes a fresh parentless commit, so old screenshots\n# become unreachable rather than accumulating in everyone's clone. Do not add files\n# to it or base work on it.\n#\n# First-rollout runbook (one-time, BEFORE this workflow can go green):\n#   1. Deploy the Worker (source: imsai-sh/dsh-1024store) so /api/v1/catalog/sync\n#      and /api/v1/registry exist.\n#   2. Set CATALOG_SYNC_TOKEN on the Worker (wrangler secret put CATALOG_SYNC_TOKEN,\n#      run from the dsh-1024store checkout) AND as a repository Actions secret here\n#      with the same value. Rotating it is a coordinated two-repo change.\n#   3. Run this workflow via workflow_dispatch (or wait for the next trigger).\n#   The sync step retries for up to ~10 minutes, so a run racing a Worker deploy\n#   normally self-heals; a run started before the secrets exist must be re-run.\n#\n# Branch protection: the final step pushes README commits to main over SSH,\n# authenticated by a write deploy key (repository secret CATALOG_DEPLOY_KEY).\n# Personal-account rulesets cannot list the GitHub Actions app as a bypass\n# actor, so the ruleset's bypass list must include \"Deploy keys\" instead —\n# see CONTRIBUTING.md \"Repository owners must protect main\".\nname: Catalog sync\n\non:\n  push:\n    branches: [main]\n    paths:\n      - 'catalog/plugins/**'\n      - 'catalog/categories.json'\n  schedule:\n    - cron: '15 5 * * *'\n  workflow_dispatch:\n    inputs:\n      refresh_screenshot:\n        description: 'Republish the homepage screenshot even when the catalog is unchanged (use after a site redesign)'\n        type: boolean\n        default: false\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: catalog-sync\n  cancel-in-progress: false\n\njobs:\n  sync:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    steps:\n      # With ssh-key set, checkout rewrites origin to the SSH URL, so the final\n      # git push authenticates as the write deploy key (\"Deploy keys\" is on the\n      # main ruleset's bypass list). When the secret is absent, checkout falls\n      # back to the default token and the README push step fails fast below.\n      - uses: actions/checkout@v4\n        with:\n          ssh-key: ${{ secrets.CATALOG_DEPLOY_KEY }}\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - name: Sync catalog entries to the D1 catalog\n        env:\n          CATALOG_SYNC_TOKEN: ${{ secrets.CATALOG_SYNC_TOKEN }}\n        run: |\n          if [ -z \"$CATALOG_SYNC_TOKEN\" ]; then\n            echo \"::error::The CATALOG_SYNC_TOKEN repository secret is not configured. Catalog entries were NOT synced to production. Create the secret with the Worker's CATALOG_SYNC_TOKEN value.\"\n            exit 1\n          fi\n          # Retry with backoff: the Worker is deployed manually from the dsh-1024store\n          # repository, so this run may race a deploy that is still rolling out (or,\n          # on first rollout, land before the Worker or its secret exists). The\n          # endpoint is an idempotent upsert reconciliation, so retries are safe.\n          for attempt in $(seq 1 20); do\n            if npm run catalog:sync; then\n              exit 0\n            fi\n            echo \"Catalog sync attempt ${attempt} failed; retrying in 30s (a Worker deploy may still be rolling out).\"\n            sleep 30\n          done\n          echo \"::error::Catalog sync failed after 20 attempts.\"\n          exit 1\n      - name: Rebuild the README projections from the catalog API\n        run: npm run readme:build\n      - name: Detect whether the projections changed\n        id: projections\n        run: |\n          if git diff --quiet -- README.md catalog/README.md; then\n            echo \"README projections are already current; nothing to commit.\"\n            echo \"changed=false\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"changed=true\" >> \"$GITHUB_OUTPUT\"\n          fi\n      # Runs before the README push so the new ?v= URL already resolves to the new\n      # image. The screenshot is published as a single parentless commit that force\n      # replaces the `assets` branch: the previous blob becomes unreachable instead of\n      # accumulating, so republishing it on every catalog change never grows the clone.\n      # A redesign that does not touch the catalog leaves the URL (and therefore the\n      # camo-cached image) unchanged, so `refresh_screenshot` republishes on demand;\n      # readers pick it up on the next catalog change.\n      # Cosmetic by nature — a site outage must not block the catalog README, so this\n      # step is allowed to fail without failing the job (the previous screenshot simply\n      # stays up, and capture-homepage.mjs refuses to publish a blank capture).\n      - name: Refresh the homepage screenshot on the assets branch\n        if: steps.projections.outputs.changed == 'true' || inputs.refresh_screenshot\n        continue-on-error: true\n        env:\n          GIT_AUTHOR_NAME: github-actions[bot]\n          GIT_AUTHOR_EMAIL: 41898282+github-actions[bot]@users.noreply.github.com\n          GIT_COMMITTER_NAME: github-actions[bot]\n          GIT_COMMITTER_EMAIL: 41898282+github-actions[bot]@users.noreply.github.com\n        run: |\n          # The runner ships no CJK font, so without this every Chinese glyph renders as\n          # a tofu box — including the plugin descriptions that show up in both locales.\n          sudo apt-get update -qq\n          sudo apt-get install -y -qq fonts-noto-cjk\n          node scripts/capture-homepage.mjs --out \"$RUNNER_TEMP/homepage.zh.png\" --lang zh-CN\n          node scripts/capture-homepage.mjs --out \"$RUNNER_TEMP/homepage.en.png\" --lang en-US\n          zh=\"$(git hash-object -w \"$RUNNER_TEMP/homepage.zh.png\")\"\n          en=\"$(git hash-object -w \"$RUNNER_TEMP/homepage.en.png\")\"\n          # git mktree requires entries in name order: \"homepage.en.png\" < \"homepage.zh.png\".\n          tree=\"$(printf '100644 blob %s\\thomepage.en.png\\n100644 blob %s\\thomepage.zh.png\\n' \"$en\" \"$zh\" | git mktree)\"\n          commit=\"$(git commit-tree \"$tree\" -m 'chore: refresh homepage screenshots')\"\n          git push --force origin \"${commit}:refs/heads/assets\"\n      - name: Commit refreshed README projections\n        if: steps.projections.outputs.changed == 'true'\n        env:\n          HAS_DEPLOY_KEY: ${{ secrets.CATALOG_DEPLOY_KEY != '' }}\n        run: |\n          if [ \"$HAS_DEPLOY_KEY\" != \"true\" ]; then\n            echo \"::error::README projections changed but the CATALOG_DEPLOY_KEY repository secret is not configured, so the push to main would be rejected by branch protection. Add a write deploy key and store its private key as CATALOG_DEPLOY_KEY.\"\n            exit 1\n          fi\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"41898282+github-actions[bot]@users.noreply.github.com\"\n          git add README.md catalog/README.md\n          git commit -m \"docs: refresh catalog readme\"\n          # main may have advanced while this run was installing/syncing (for\n          # example an auto-merged plugin PR). Rebase and retry instead of failing\n          # on a non-fast-forward push; rebase conflicts cannot occur because this\n          # bot is the only writer of the generated README files and runs are\n          # serialized by the catalog-sync concurrency group.\n          for attempt in 1 2 3; do\n            if git push; then\n              exit 0\n            fi\n            echo \"git push attempt ${attempt} rejected; rebasing onto the latest main and retrying.\"\n            git pull --rebase origin main\n          done\n          git push\n"
    },
    {
      "path": ".github/workflows/plugin-review.yml",
      "content": "name: Plugin submission review\n\non:\n  pull_request_target:\n    branches: [main]\n    types: [opened, synchronize, reopened, ready_for_review]\n\nconcurrency:\n  group: plugin-submission-${{ github.event.pull_request.number }}\n  cancel-in-progress: true\n\npermissions:\n  contents: read\n\njobs:\n  static-review:\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    permissions:\n      contents: read\n      # GitHub Actions requires pull-request write access for PR issue comments.\n      # The trusted reviewer only calls comment endpoints; it never updates PR state.\n      pull-requests: write\n    outputs:\n      # auto-merge | manual-review | rejected — decided by the trusted reviewer.\n      verdict: ${{ steps.review.outputs.verdict }}\n    steps:\n      - name: Check out trusted reviewer\n        uses: actions/checkout@v4\n        with:\n          # The base BRANCH, not the event's base.sha. base.sha is frozen at the\n          # revision main had when the pull request was opened, and reopening\n          # does not refresh it — pinning to it means a fix to this reviewer can\n          # never reach a pull request that was opened before the fix landed.\n          ref: ${{ github.event.pull_request.base.ref }}\n          path: reviewer\n          persist-credentials: false\n      - name: Check out submitted files as data\n        uses: actions/checkout@v4\n        with:\n          # checkout's fork guard exists to stop pull_request_target workflows\n          # from RUNNING fork code in a trusted context. This job never executes\n          # anything from this checkout: every script comes from the base-branch\n          # \"reviewer\" checkout above, this path is only parsed as data, and\n          # persist-credentials is off. Removing this opt-in makes every fork PR\n          # fail here, before the reviewer can run or comment.\n          allow-unsafe-pr-checkout: true\n          repository: ${{ github.event.pull_request.head.repo.full_name }}\n          ref: ${{ github.event.pull_request.head.sha }}\n          path: submission\n          persist-credentials: false\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - name: Check submitted files and DeepSeek Harness plugin manifest\n        id: review\n        run: node reviewer/scripts/review-plugin-submission.mjs\n        env:\n          GITHUB_TOKEN: ${{ github.token }}\n          PLUGIN_REVIEW_REPOSITORY: ${{ github.repository }}\n          PLUGIN_REVIEW_PULL_NUMBER: ${{ github.event.pull_request.number }}\n          PLUGIN_REVIEW_ROOT: ${{ github.workspace }}/submission\n\n  merge:\n    needs: static-review\n    # Only the single-new-entry fast path is merged automatically. Modification\n    # and deletion PRs pass static review with verdict=manual-review and MUST be\n    # merged by a maintainer by hand.\n    if: ${{ !github.event.pull_request.draft && needs.static-review.outputs.verdict == 'auto-merge' }}\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    permissions:\n      contents: write\n      actions: write\n    steps:\n      - name: Check out trusted merger\n        uses: actions/checkout@v4\n        with:\n          # Same reasoning as the reviewer checkout above: always the latest\n          # trusted revision of the base branch, never the frozen base.sha.\n          ref: ${{ github.event.pull_request.base.ref }}\n          path: reviewer\n          persist-credentials: false\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - name: Squash-merge the validated head\n        run: node reviewer/scripts/merge-plugin-submission.mjs\n        env:\n          GITHUB_TOKEN: ${{ github.token }}\n          PLUGIN_REVIEW_REPOSITORY: ${{ github.repository }}\n          PLUGIN_REVIEW_PULL_NUMBER: ${{ github.event.pull_request.number }}\n          PLUGIN_REVIEW_EXPECTED_HEAD_SHA: ${{ github.event.pull_request.head.sha }}\n          PLUGIN_REVIEW_EXPECTED_BASE_REF: main\n      # Pushes made with the default GITHUB_TOKEN never fire other workflows'\n      # push triggers (GitHub's recursion guard), so the squash merge above\n      # does NOT start catalog-sync by itself. workflow_dispatch is exempt from\n      # that guard — chain the sync explicitly so every auto-merged submission\n      # reaches D1 and the README without waiting for the daily cron.\n      - name: Chain catalog sync after the merge\n        run: gh workflow run catalog-sync.yml --repo \"$GH_REPO\"\n        env:\n          GH_TOKEN: ${{ github.token }}\n          GH_REPO: ${{ github.repository }}\n"
    },
