    {
      "path": "scripts/build-readme.mjs",
      "content": "#!/usr/bin/env node\n\nimport { createHash } from 'node:crypto'\nimport { readFile, writeFile } from 'node:fs/promises'\nimport path from 'node:path'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\n\nimport { assert, isObject, readCategories, sourceUrl } from './lib/catalog-entry.mjs'\n\nconst scriptRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')\nexport const defaultBase = 'https://deepseek1024.com'\n// Must stay aligned with UNCLASSIFIED_CATEGORY in web/worker/lib/categories.ts\n// of the dsh-1024store repository (the website/API label for the same bucket); no CI\n// spans the two repos, so keep them aligned by hand.\nconst unclassifiedLabel = { en: 'Unclassified', zh: '待分类' }\nconst generatedNotice = {\n  zh: '<!-- 本文件由 scripts/build-readme.mjs 从 deepseek1024.com 目录 API 自动生成，请勿手工编辑。 -->',\n  en: '> This file is generated by `scripts/build-readme.mjs` from the DSH 1024Store catalog API. Do not edit it directly.',\n}\n\nfunction text(value) {\n  return typeof value === 'string' ? value.replace(/\\s+/g, ' ').trim() : ''\n}\n\nfunction updatedDate(value) {\n  const date = typeof value === 'string' ? value.slice(0, 10) : ''\n  assert(/^\\d{4}-\\d{2}-\\d{2}$/.test(date), `Registry has an invalid updated timestamp: ${String(value)}`)\n  return date\n}\n\nfunction normalizePlugin(plugin, id, stars) {\n  assert(isObject(plugin), 'Registry contains an invalid plugin entry')\n  const name = text(plugin.name)\n  const url = typeof plugin.url === 'string' ? plugin.url : ''\n  assert(name.length > 0 && /^https:\\/\\/github\\.com\\//.test(url), `Registry plugin ${id} must have a name and GitHub url`)\n  return {\n    id,\n    name,\n    owner: text(plugin.owner),\n    url,\n    category: typeof plugin.category === 'string' && plugin.category.length > 0 ? plugin.category : 'unclassified',\n    description: {\n      en: text(plugin.description?.en),\n      zh: text(plugin.description?.zh),\n    },\n    added: typeof plugin.added === 'string' ? plugin.added : null,\n    stars,\n  }\n}\n\nexport function normalizeRegistry(data) {\n  assert(isObject(data) && Array.isArray(data.plugins), 'Registry response must contain a plugins array')\n  // A capped /api/v1/registry response advertises the full catalog size in\n  // `total` while serving only its install-ranked head. Regenerating from it —\n  // over the network or via --from-file — would silently shrink the README to\n  // the cap, so it is refused here, in the one place every registry-shaped\n  // payload passes through.\n  assert(\n    typeof data.total !== 'number' || data.total <= data.plugins.length,\n    'The registry payload is capped and cannot rebuild the README; use a full-catalog source such as /api/v2/plugins',\n  )\n  return {\n    updated: updatedDate(data.updated),\n    plugins: data.plugins.map(plugin => {\n      assert(isObject(plugin) && typeof plugin.id === 'string' && /^[^/]+\\/[^/]+(\\/[^/]+)*$/.test(plugin.id), 'Registry plugins must carry an owner/repository[/sub/dir] id')\n      return normalizePlugin(plugin, plugin.id, Number.isInteger(plugin.stars) ? plugin.stars : null)\n    }),\n  }\n}\n\nexport function adaptLegacyRegistry(data) {\n  assert(isObject(data) && Array.isArray(data.plugins), 'Legacy /plugins.json must contain a plugins array')\n  return {\n    updated: updatedDate(data.updated),\n    plugins: data.plugins.map(plugin => {\n      assert(isObject(plugin) && typeof plugin.url === 'string', 'Legacy plugins must carry a url')\n      const derived = new URL(plugin.url).pathname.replace(/^\\/+/, '').replace(/\\/+$/, '')\n      const id = /^[^/]+\\/[^/]+$/.test(derived) ? derived : `${plugin.owner}/${plugin.name}`\n      return normalizePlugin(plugin, id, null)\n    }),\n  }\n}\n\nfunction detectRegistryShape(data) {\n  const plugins = isObject(data) ? data.plugins : undefined\n  const first = Array.isArray(plugins) ? plugins.find(value => isObject(value)) : undefined\n  if (first !== undefined && typeof first.id !== 'string') return adaptLegacyRegistry(data)\n  return normalizeRegistry(data)\n}\n\nconst v2PageLimit = 200\n// One sort per attempt. Membership does not depend on the sort, but the edge\n// cache keys on it, so a retry under a different real sort value reads fresh\n// origin pages instead of replaying whichever mixed cached copies just failed\n// the consistency check. (The edge cache deliberately strips unknown params,\n// so a synthetic cache-buster would not work.)\nconst v2SweepSorts = ['name', 'active', 'newest']\nconst v2SweepRetryDelayMs = 10_000\n\nfunction v2PageUrl(base, sort, page) {\n  return `${base}/api/v2/plugins?sort=${sort}&limit=${v2PageLimit}&page=${page}`\n}\n\n// The README needs the whole catalog, and /api/v1/registry no longer serves it\n// (the endpoint caps at its install-ranked head), so the projections page\n// through /api/v2/plugins instead. A page sweep is not atomic — the 15-minute\n// KV snapshot can rotate mid-sweep, the edge can hold pages cached from\n// different snapshots, and a single page can hit a transient 5xx — so a sweep\n// only counts when every page arrives, reports the same generatedAt, and the\n// pages add up to the advertised total; anything else retries under the next\n// sort, and a persistent failure fails the build rather than publishing a\n// partial listing.\nasync function loadPagedCatalog(fetchImplementation, base, retryDelayMs = v2SweepRetryDelayMs) {\n  let lastError = null\n  for (const [attempt, sort] of v2SweepSorts.entries()) {\n    if (attempt > 0 && retryDelayMs > 0) {\n      await new Promise(resolve => setTimeout(resolve, retryDelayMs))\n    }\n    const firstResponse = await fetchImplementation(v2PageUrl(base, sort, 1))\n    if (firstResponse.status === 404) return null\n    if (!firstResponse.ok) {\n      lastError = new Error(`GET ${base}/api/v2/plugins failed: HTTP ${firstResponse.status}`)\n      continue\n    }\n    const first = JSON.parse(await firstResponse.text())\n    assert(\n      isObject(first) && Array.isArray(first.plugins)\n        && Number.isInteger(first.totalPages) && first.totalPages >= 1\n        && Number.isInteger(first.total) && typeof first.generatedAt === 'string',\n      'The /api/v2/plugins response is missing its pagination metadata',\n    )\n    const plugins = [...first.plugins]\n    let attemptError = null\n    for (let page = 2; page <= first.totalPages; page += 1) {\n      const response = await fetchImplementation(v2PageUrl(base, sort, page))\n      if (!response.ok) {\n        attemptError = new Error(`GET ${base}/api/v2/plugins page ${page} failed: HTTP ${response.status}`)\n        break\n      }\n      const body = JSON.parse(await response.text())\n      if (!isObject(body) || !Array.isArray(body.plugins) || body.generatedAt !== first.generatedAt) {\n        attemptError = new Error('The catalog snapshot rotated while paging /api/v2/plugins; the sweep was inconsistent')\n        break\n      }\n      plugins.push(...body.plugins)\n    }\n    if (attemptError === null) {\n      const ids = new Set(plugins.map(plugin => (isObject(plugin) ? plugin.id : undefined)))\n      if (plugins.length === first.total && ids.size === plugins.length) {\n        return normalizeRegistry({ updated: first.generatedAt, plugins })\n      }\n      attemptError = new Error('The /api/v2/plugins sweep did not add up to the advertised catalog total')\n    }\n    lastError = attemptError\n  }\n  throw lastError\n}\n\nexport async function loadRegistry(options = {}) {\n  if (options.fromFile !== undefined) {\n    return detectRegistryShape(JSON.parse(await readFile(options.fromFile, 'utf8')))\n  }\n  const fetchImplementation = options.fetchImplementation ?? globalThis.fetch\n  const base = (options.base ?? defaultBase).replace(/\\/+$/, '')\n  const paged = await loadPagedCatalog(fetchImplementation, base, options.retryDelayMs)\n  if (paged !== null) return paged\n  // v2 not deployed yet: the original bootstrap chain. normalizeRegistry\n  // refuses a capped registry response (total larger than the entries served)\n  // instead of silently shrinking the README to the cap.\n  const registryResponse = await fetchImplementation(`${base}/api/v1/registry`)\n  if (registryResponse.ok) {\n    return normalizeRegistry(JSON.parse(await registryResponse.text()))\n  }\n  if (registryResponse.status !== 404) {\n    throw new Error(`GET ${base}/api/v1/registry failed: HTTP ${registryResponse.status}`)\n  }\n  const legacyResponse = await fetchImplementation(`${base}/plugins.json`)\n  if (!legacyResponse.ok) {\n    throw new Error(`GET ${base}/plugins.json fallback failed: HTTP ${legacyResponse.status}`)\n  }\n  return adaptLegacyRegistry(JSON.parse(await legacyResponse.text()))\n}\n\nfunction comparePlugins(left, right) {\n  const leftName = left.name.toLocaleLowerCase('en-US')\n  const rightName = right.name.toLocaleLowerCase('en-US')\n  return leftName.localeCompare(rightName, 'en-US')\n    || left.name.localeCompare(right.name, 'en-US')\n    || left.id.localeCompare(right.id, 'en-US')\n}\n\nexport function groupPlugins(registry, categories) {\n  const ordered = [...categories].sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || String(left.id).localeCompare(String(right.id), 'en-US'))\n  const buckets = new Map(ordered.map(category => [category.id, []]))\n  const unclassified = []\n  for (const plugin of registry.plugins) {\n    (buckets.get(plugin.category) ?? unclassified).push(plugin)\n  }\n  const groups = ordered\n    .filter(category => buckets.get(category.id).length > 0)\n    .map(category => ({\n      id: category.id,\n      label: category.label,\n      plugins: [...buckets.get(category.id)].sort(comparePlugins),\n    }))\n  if (unclassified.length > 0) {\n    groups.push({ id: 'unclassified', label: unclassifiedLabel, plugins: [...unclassified].sort(comparePlugins) })\n  }\n  return groups\n}\n\nfunction pluginLine(plugin, locale) {\n  const preferred = plugin.description[locale]\n  const fallback = locale === 'zh' ? plugin.description.en : plugin.description.zh\n  const description = preferred.length > 0 ? preferred : fallback\n  // The plugin's own directory, not its repository: a monorepo contributes one\n  // line per package, and pointing them all at the repository root would make\n  // every line but the first a dead end for the reader.\n  const href = sourceUrl(plugin.id)\n  return description.length > 0\n    ? `- [${plugin.name}](${href}) — ${description}`\n    : `- [${plugin.name}](${href})`\n}\n\n// The homepage screenshot lives on a dedicated orphan `assets` branch that CI\n// force-pushes to a single commit, so republishing it never grows the repository.\n// GitHub proxies README images through camo and keys that cache on the URL, so a\n// stable URL would leave readers looking at a stale screenshot. The cache-buster is\n// derived from the catalog contents rather than the clock: the image URL changes\n// exactly when the plugin list changes, which keeps the screenshot in step with the\n// list without producing a README commit on every no-op sync.\nexport const screenshotBranch = 'assets'\n// One capture per language: the site picks its locale from navigator.language, so each\n// projection shows the store in the language its readers are reading.\nexport const screenshotPaths = { zh: 'homepage.zh.png', en: 'homepage.en.png' }\nconst screenshotRepository = 'imsai-sh/awesome-deepseek-harness-plugins'\n\nexport function catalogRevision(registry) {\n  const material = registry.plugins.map(plugin => `${plugin.id}\\u0000${plugin.category}`).join('\\n')\n  return createHash('sha256').update(`${registry.updated}\\n${material}`).digest('hex').slice(0, 12)\n}\n\nfunction heroImage(registry, locale) {\n  const alt = locale === 'zh' ? 'DSH 1024Store 插件市场首页' : 'The DSH 1024Store plugin marketplace homepage'\n  const source = `https://raw.githubusercontent.com/${screenshotRepository}/${screenshotBranch}/${screenshotPaths[locale]}?v=${catalogRevision(registry)}`\n  return `[![${alt}](${source})](https://deepseek1024.com/)`\n}\n\nfunction communityQr() {\n  return `<div align=\"center\">\n  <strong>DSH插件社区</strong><br><br>\n  <img src=\"docs/assets/wechat-group.jpg\" alt=\"DSH插件社区微信二维码\" width=\"280\">\n</div>`\n}\n\n// GitHub stops rendering Markdown at 500 KiB and gives no truncation notice: every\n// entry past that byte offset simply does not exist for readers. Measured against the\n// live catalog on 2026-08-16, an uncapped projection was 594 KB and silently dropped\n// its last 479 plugins.\n//\n// The cap is a byte budget, not an entry count, because an entry costs whatever its\n// rendered line costs and that cost moves under us. A fixed 500-entry cap on the\n// auto-discovered `unclassified` bucket held only while that bucket was the sole one\n// big enough to matter and its lines were short. The classification pass ended both\n// conditions in one go: it gave every entry a bilingual description (roughly doubling\n// the average line) and emptied `unclassified` into the curated categories, so a cap\n// keyed to a bucket and counted in entries had nothing left to trim and reported no\n// truncation while the projection sailed 210 KB past the limit. Any entry count that\n// fits today is a silent truncation the next time descriptions grow, so the budget is\n// measured in the only unit GitHub actually enforces.\n//\n// Both projections are budgeted separately: the same entry costs about three bytes per\n// Chinese character in README.md against one per ASCII character in catalog/README.md,\n// and the two descriptions are written independently, so one shared entry count would\n// truncate one file needlessly while overshooting the other. Each locale is fitted in\n// two passes — render the whole file with every list emptied to price what is not the\n// lists themselves (prose, index, summaries, truncation notices), then split what is\n// left between the groups.\n//\n// That split is max-min fair (see `fairShares`) rather than first-come: a category that\n// needs less than an equal share is listed in full and releases the surplus, so only\n// the genuinely oversized categories are cut, and never so that an earlier one can be\n// whole at a later one's expense. Curated categories are served first and `unclassified`\n// takes the leftover, which reproduces the old rule exactly whenever the curated set\n// fits: full curated lists, `unclassified` capped.\n//\n// Every pass reads sorted arrays and integer byte counts, so the same input always\n// yields the same output: no clock, no Map iteration order, no hashing. Each list keeps\n// its natural (name) ordering — `added` carries no usable ordering signal here, since\n// the topic-scan backfill gave most of the catalog the same date.\nexport const githubRenderLimit = 500 * 1024\n// Headroom below the hard limit. The fitted lists land just under `limit - margin`; the\n// margin absorbs the few bytes the counts in each summary and truncation notice gain as\n// the lists fill, and leaves room for GitHub to be stricter than we measure.\nconst renderSafetyMargin = 8 * 1024\n\n// An entry costs its rendered bytes plus the newline that joins it to the list.\nfunction entryCost(plugin, locale) {\n  return Buffer.byteLength(pluginLine(plugin, locale), 'utf8') + 1\n}\n\nfunction listCost(group, locale) {\n  return group.plugins.reduce((total, plugin) => total + entryCost(plugin, locale), 0)\n}\n\nfunction withVisiblePlugins(group, locale, budget) {\n  const visible = []\n  let spent = 0\n  for (const plugin of group.plugins) {\n    const cost = entryCost(plugin, locale)\n    if (spent + cost > budget) break\n    spent += cost\n    visible.push(plugin)\n  }\n  return { ...group, total: group.plugins.length, visible, capped: visible.length < group.plugins.length }\n}\n\n// Max-min fair split of `budget` over the given list costs: every group may spend an\n// equal share, a group that needs less than its share takes only what it needs and\n// releases the surplus, and the round repeats until no group is newly satisfied. Small\n// categories are therefore never truncated to make room for a large one. Returns the\n// per-group allowance in input order plus whatever is still unspent.\nfunction fairShares(costs, budget) {\n  const shares = costs.map(() => 0)\n  let open = costs.map((_, index) => index)\n  let remaining = budget\n  while (open.length > 0) {\n    const share = Math.floor(remaining / open.length)\n    const satisfied = open.filter(index => costs[index] <= share)\n    if (satisfied.length === 0) {\n      for (const index of open) shares[index] = share\n      remaining -= share * open.length\n      break\n    }\n    for (const index of satisfied) {\n      shares[index] = costs[index]\n      remaining -= costs[index]\n    }\n    open = open.filter(index => costs[index] > share)\n  }\n  return { shares, remaining }\n}\n\n// Pass one prices the projection with every list emptied: a zero budget still renders\n// each summary and truncation notice, so the measurement covers every byte the finished\n// file spends outside the lists. Whatever is left under the limit is what pass two may\n// spend on entries.\nfunction fitGroups(registry, groups, locale) {\n  const emptied = groups.map(group => withVisiblePlugins(group, locale, 0))\n  const overhead = Buffer.byteLength(renderReadme(registry, groups, emptied, locale), 'utf8')\n  const budget = Math.max(githubRenderLimit - renderSafetyMargin - overhead, 0)\n  const curated = groups.map((group, index) => index).filter(index => groups[index].id !== 'unclassified')\n  const { shares, remaining } = fairShares(curated.map(index => listCost(groups[index], locale)), budget)\n  // Anything outside the curated set — in practice only `unclassified` — is served last,\n  // out of what the curated categories left behind.\n  const budgets = groups.map(() => remaining)\n  curated.forEach((groupIndex, shareIndex) => { budgets[groupIndex] = shares[shareIndex] })\n  return groups.map((group, index) => withVisiblePlugins(group, locale, budgets[index]))\n}\n\nexport function assertRenderable(files) {\n  for (const [relative, content] of Object.entries(files)) {\n    const bytes = Buffer.byteLength(content, 'utf8')\n    assert(\n      bytes <= githubRenderLimit,\n      `${relative} is ${bytes} bytes; GitHub renders at most ${githubRenderLimit} and silently drops everything past that offset. The plugin lists are already fitted to a byte budget, so this means everything around them — prose, the category index, the per-category summaries — no longer fits: trim that copy or raise renderSafetyMargin in scripts/build-readme.mjs.`,\n    )\n  }\n}\n\nfunction escapeHtml(value) {\n  return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n}\n\nfunction categoryIndex(groups, locale) {\n  return groups.map(group => `- [${group.label[locale]}](#${group.id}) (${group.plugins.length})`).join('\\n')\n}\n\n// Each category is a collapsed <details> block: the full list is ~3k entries, so an\n// expanded README buries everything above it. GitHub only renders Markdown inside\n// <details> when the element is unindented and the <summary> is followed by a blank\n// line, and category labels contain \"&\", so the summary text must be HTML-escaped.\n// The <a id> anchor stays outside the block so the category index still jumps to a\n// collapsed group.\nfunction categorySections(prepared, locale) {\n  return prepared.map(group => {\n    const count = group.capped\n      ? (locale === 'zh' ? `显示 ${group.visible.length} / 共 ${group.total} 个` : `showing ${group.visible.length} of ${group.total}`)\n      : (locale === 'zh' ? `${group.total} 个插件` : `${group.total} plugins`)\n    const lines = group.visible.map(plugin => pluginLine(plugin, locale))\n    if (group.capped) {\n      const rest = group.total - group.visible.length\n      lines.push(locale === 'zh'\n        ? `- *GitHub 单个文件能渲染的长度有上限，本分类还有 ${rest} 个插件没能列在这里；完整目录请在[在线网站](https://deepseek1024.com/)搜索浏览。*`\n        : `- *GitHub only renders so much of one file, so ${rest} more plugins in this category did not fit here — search or browse the full catalog on the [live website](https://deepseek1024.com/).*`)\n    }\n    return [\n      `<a id=\"${group.id}\"></a>`,\n      '',\n      '<details>',\n      `<summary><strong>${escapeHtml(group.label[locale])}</strong> · ${count}</summary>`,\n      '',\n      lines.join('\\n'),\n      '',\n      '</details>',\n    ].join('\\n')\n  }).join('\\n\\n')\n}\n\nfunction chineseReadme(registry, groups, prepared) {\n  const total = registry.plugins.length\n  return `# Awesome DeepSeek Harness Plugins\n\n${generatedNotice.zh}\n\n面向 [DeepSeek Harness](https://github.com/deepseek-ai/DeepSeek-Harness)（\\`dsh\\`）生态的社区插件目录，共收录 **${total}** 个插件（含 PR 收录与 GitHub \\`dsh-plugin\\` topic 自动发现），目录数据更新于 ${registry.updated}。\n\n> 📦 **仓库拆分公告**：自 2026-08-25 起，deepseek1024.com 网站与 \\`dsh1024\\` CLI 的源码已拆分至独立仓库 [imsai-sh/dsh-1024store](https://github.com/imsai-sh/dsh-1024store)。本仓库从此专注插件目录（awesome 清单）与收录流程；网站与 CLI 相关的 issue / PR 请移步新仓库，插件收录照旧在这里提交。\n\n**但这个项目不只是一份 awesome list。** 它还包括一个在线插件市场、一个把市场装进 \\`dsh\\` 本体的插件，以及一套免费的公开查询 API——这些应用代码开源在姊妹仓库 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)；本仓库专注目录本身：经静态校验的 PR 收录流水线与自动生成的目录 README，目录数据另有自动收集服务持续喂入。全部代码 MIT 协议，fork 之后就能部署成你自己的插件市场。\n\n${heroImage(registry, 'zh')}\n\n[在线网站](https://deepseek1024.com/) · [API 文档](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/api.md) · [英文目录](catalog/README.md) · [提交插件](CONTRIBUTING.md) · [网站与 CLI 源码](https://github.com/imsai-sh/dsh-1024store)\n\n[![GitHub Stars](https://img.shields.io/github/stars/imsai-sh/awesome-deepseek-harness-plugins?style=social)](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/stargazers)\n\n${communityQr()}\n\n## 项目亮点\n\n### 在线插件市场（开源 · 可一键自部署）\n\n[deepseek1024.com](https://deepseek1024.com/) 提供搜索、分类筛选、安装排行榜、插件详情与 GitHub 活跃度数据。整站跑在 Cloudflare Workers + D1 + KV 上，源码在 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store) 的 [\\`web\\`](https://github.com/imsai-sh/dsh-1024store/tree/main/web)。\n\n想要一个完全属于自己的插件市场：fork [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)，把 \\`web/wrangler.jsonc\\` 里的 \\`routes\\` 换成你自己的域名，创建 D1 数据库与 KV 命名空间，配齐 \\`secrets.required\\` 列出的 Worker secret，然后本地执行 \\`npm run db:migrate:remote\\` 和 \\`npm run deploy\\` 完成部署（部署是显式的本地操作，push 不会自动上线）。完整步骤见该仓库的[部署文档](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/deployment.md)。\n\n### 把插件市场装进 dsh 本体\n\n不想切浏览器，就把市场本身作为插件装进 DeepSeek Harness：\n\n\\`\\`\\`bash\ndsh plugin --profile web add dsh1024@latest\n\\`\\`\\`\n\n重启后「设置」里会出现独立的 **1024 Store** 入口，「设置 → 插件」下也会多出一个 **1024 Store（数量）** 标签页，可以直接搜索目录、按分类筛选、识别已安装状态、安装与卸载，并显示操作进度。安装器只接受目录 API 返回并通过严格语法校验的结构化目标：优先使用已发布 npm 包，否则使用与插件 ID、仓库 URL 一致的 GitHub 源码规格；展示命令不会被直接执行。源码见 [\\`plugin\\`](https://github.com/imsai-sh/dsh-1024store/tree/main/plugin)。\n\n### 定时自动收集 + 格式校验\n\n这是本目录与多数插件市场最大的区别：**目录不靠人肉维护，收录前一定过校验。**\n\n- **定时收集**：自动收录带 \\`dsh-plugin\\` topic 的 GitHub 仓库，增量抓取新建与新推送的仓库，并定期全量对账——长期不活跃的仓库不会被漏收，掉了 topic 也只在一次成功的全量对账后才下架。\n- **格式校验**：每个候选仓库都要通过静态校验——读取默认分支的 Git tree，检查 \\`package.json\\`、\\`dsh.bundle.patch\\` 字段，以及 patch 文件在同一棵 tree 中确实存在。**全程只读文件，绝不安装依赖、绝不执行仓库代码。** 校验不通过就不进目录。\n- **自动同步**：PR 合并后由 CI 自动同步目录到网站数据库并刷新本 README，贡献者和维护者都不需要手工改任何生成文件。\n\n数据来源与校验语义见 [目录数据来源文档](docs/plugin-discovery.md)。\n\n### 免费查询 API\n\n目录数据免费开放，匿名即可调用：\n\n\\`\\`\\`bash\ncurl 'https://api.deepseek1024.com/v1/plugins/search?q=memory'\n\\`\\`\\`\n\n匿名调用每天 50 次、每分钟 10 次；用 GitHub 账号登录网站创建 API Key 后提升到每天 500 次、每分钟 30 次。另有 \\`/api/v1/registry\\` 返回按安装热度排序的精简目录快照（至多 500 条）。完整端点、参数与错误码见 [API 参考](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/api.md)。\n\n## 参与进来\n\n这个项目由社区维护，下面每一种参与都真的有用：\n\n- **点个 Star** — [Star 本仓库](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/stargazers)是成本最低、帮助最大的支持，能让更多 DeepSeek Harness 用户找到这里。\n- **提 Issue** — 插件信息有误、分类不合理、网站或 API 有问题、想要新功能，都欢迎[提 Issue](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/issues/new)。\n- **发 PR** — [提交你自己的插件](CONTRIBUTING.md)或改进目录流水线，欢迎直接发 [Pull Request](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/pulls)；网站、CLI 与市场插件的改进请发到 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)。\n- **Fork 自建** — 想要自己的插件市场，[Fork dsh-1024store](https://github.com/imsai-sh/dsh-1024store/fork) 之后按上面的步骤配置即可，MIT 协议，随便改。\n\n## 安装插件并计入统计\n\n1024 Store 只提供 npm 安装：插件详情页展示的命令安装的是作者发布到 npm、声明 \\`dsh.bundle\\` 的包；尚未发布 npm 包的插件以浏览模式收录（有仓库链接，无安装命令）。网站优先提供开源包装 CLI；它会调用官方 DeepSeek Harness 插件命令、校验 profile 的真实安装结果，并把匿名安装结果可靠地上报到排行榜：\n\n\\`\\`\\`bash\ndsh1024 plugin --profile web add <npm-package>\n\\`\\`\\`\n\n首次使用先一次性全局安装：\\`npm install -g dsh1024\\`。它与官方命令只差一个名字——\\`plugin\\` 之后的参数原样转发给官方 CLI，不增删、不改写、不重排，包装器只负责在结束后核对 profile 并记录一条匿名安装结果。参数不会写入遥测或本地 receipt。\n\nmonorepo 子目录插件的标识形如 \\`owner/repo/packages/foo\\`，每个子包发布并安装自己的 npm 包，同仓库的兄弟插件各自独立计数。\n\n统计身份是保存在 \\`$DSH_HOME/.dsh-1024store/\\` 的随机安装实例 ID，不是实名用户或账号。CLI 不上传命令输出、路径、用户名、环境变量、会话内容或原始错误；可用 \\`npx dsh1024 telemetry disable\\`、\\`DO_NOT_TRACK=1\\` 或 \\`DSH1024_TELEMETRY=0\\`（旧变量名 \\`DSH_1024STORE_TELEMETRY\\` 仍兼容）关闭。直接使用官方 \\`dsh plugin\\` 命令仍然可用，但不会计入 DSH 1024Store 安装统计。详细字段、口径、存储和部署方式见 [安装统计设计](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/install-analytics.md)，CLI 源码见 [\\`plugin\\`](https://github.com/imsai-sh/dsh-1024store/tree/main/plugin)。\n\n## 提交插件\n\n### 使用 Agent Skill 提交（推荐）\n\n如果你使用 Codex、Claude Code、Cursor 或其他兼容 Agent Skills 的编程助手，可以安装本仓库提供的提交 Skill：\n\n\\`\\`\\`bash\nnpx skills add imsai-sh/awesome-deepseek-harness-plugins --skill submit-dsh-plugin -g\n\\`\\`\\`\n\n安装后告诉助手：\n\n\\`\\`\\`text\n使用 $submit-dsh-plugin 检查并提交我的 DeepSeek Harness 插件。\n\\`\\`\\`\n\n该 Skill 会检查插件仓库、生成唯一允许提交的目录 JSON、验证变更范围，并在获得授权后创建 PR。新增条目的非草稿 PR 通过静态审查后会自动合并；修改或删除既有条目的 PR 同样会跑静态审查，但不会自动合并，需要维护者人工审核后手动合并。合并后 CI 自动同步目录到网站数据库并刷新本 README，贡献者和维护者都不需要手工更新任何生成文件。查看 [Skill 源码](skills/submit-dsh-plugin/SKILL.md)。\n\n### 手动提交\n\n欢迎把你的 DeepSeek Harness 插件提交到本目录。请阅读 [CONTRIBUTING.md](CONTRIBUTING.md)，通过 PR 提交一个新的结构化插件文件；自动审查将验证提交范围和最基础的 DeepSeek Harness 插件配置，通过后自动合并，并由 CI 自动同步到网站与本 README。需要修正或下架既有条目时也可以发 PR，静态审查照常运行，但这类 PR 由维护者人工审核后合并。\n\n安装命令以插件详情页展示的 npm 包为准：\\`dsh1024 plugin --profile web add <npm-package>\\`（首次使用先 \\`npm install -g dsh1024\\`）。\n\n## 项目定位\n\n本项目与 [awesome-dsh-plugin](https://github.com/awesome-dsh-plugin/awesome-dsh-plugin) 都服务于 DeepSeek Harness 插件生态。在继承其目录数据与社区整理思路的基础上，本项目把「一份人工维护的列表」扩展成一套开源、可自部署的插件市场基建：在线市场网站、dsh 内置市场插件、静态校验的 PR 收录流水线与免费查询 API，并由自动收集服务持续补充目录数据，具体见上文[项目亮点](#项目亮点)。\n\n## 项目结构\n\n\\`\\`\\`text\ncatalog/plugins/    插件提交表单与 curated 元数据（每个插件一个 JSON）\ncatalog/categories.json  分类定义（唯一分类信源）\ncatalog/schema/     插件提交 JSON Schema\nskills/             面向贡献者的可安装 Agent Skills\nscripts/            提交审查、目录同步与 README 生成脚本\ndocs/               目录数据模型文档\n\\`\\`\\`\n\n网站与 CLI 的源码（\\`web\\` 与 \\`plugin\\`）在姊妹仓库 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)。线上目录数据的唯一信源是 Cloudflare D1；本 README 与 [catalog/README.md](catalog/README.md) 由 CI 从目录 API 全量生成，职责划分见 [仓库布局](docs/repository-layout.md)。\n\n## 网站与 CLI 的本地运行与部署\n\n网站与 CLI 的本地开发、D1 迁移与 Cloudflare 部署流程都在 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)：见其 [README](https://github.com/imsai-sh/dsh-1024store#readme) 与[部署文档](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/deployment.md)。本仓库只需要 Node.js 22+ 与 \\`npm ci && npm test\\` 即可参与目录流水线开发。\n\n## 致谢\n\n感谢以下项目为本目录提供基础与参考：\n\n- [DeepSeek Harness](https://github.com/deepseek-ai/deepseek-harness)：提供插件系统、\\`dsh.bundle\\` 规范和插件开发文档。\n- [awesome-dsh-plugin](https://github.com/awesome-dsh-plugin/awesome-dsh-plugin)：提供初始插件目录数据和社区目录设计参考。\n\n## 插件分类\n\n分组默认折叠，点开即可展开。GitHub 对单个文件的渲染长度有上限，条目较多的分类只列出其中一部分（分类标题会写明列出了多少），完整目录请在[在线网站](https://deepseek1024.com/)搜索浏览。\n\n${categoryIndex(groups, 'zh')}\n\n${categorySections(prepared, 'zh')}\n\n## 免责声明\n\n本项目是社区维护的插件索引。插件由各自作者开发和维护，收录不构成安全、质量或维护状态背书。安装插件会在本机运行第三方代码，请在安装前自行审阅源码和依赖。\n\n## 许可证\n\n本仓库采用分区许可：\n\n- 目录自动化与脚本等源代码采用 [MIT License](LICENSE)（网站与 CLI 源码在 [dsh-1024store](https://github.com/imsai-sh/dsh-1024store)，同为 MIT）。\n- \\`catalog/\\` 下的插件目录元数据采用 [CC0-1.0](catalog/LICENSE)。\n- 初始目录数据导入自 \\`awesome-dsh-plugin\\`，来源和导入提交见 [catalog/ATTRIBUTION.md](catalog/ATTRIBUTION.md)。\n\n目录中列出的第三方插件不属于本仓库，其源代码分别遵循各自仓库的许可证。\n`\n}\n\nfunction englishReadme(registry, groups, prepared) {\n  const total = registry.plugins.length\n  return `# Awesome DeepSeek Harness Plugins\n\n${generatedNotice.en}\n\nThe **DSH 1024Store** community catalog for [DeepSeek Harness](https://github.com/deepseek-ai/DeepSeek-Harness) plugins: **${total}** plugins, updated ${registry.updated}.\n\n> 📦 **Repository split**: as of 2026-08-25, the deepseek1024.com site and the \\`dsh1024\\` CLI live in their own repository, [imsai-sh/dsh-1024store](https://github.com/imsai-sh/dsh-1024store). This repository is now the plugin catalog (the awesome list) and its submission pipeline only; file site/CLI issues and PRs over there — plugin submissions still happen here.\n\n**This project is more than an awesome list.** It also ships a hosted plugin marketplace, a plugin that puts that marketplace inside \\`dsh\\` itself, and a free public query API — that application code lives in the sibling repository [dsh-1024store](https://github.com/imsai-sh/dsh-1024store); this repository is the catalog itself: a statically validated PR submission pipeline and the generated directory READMEs, with an automated collection service feeding the data. Everything is MIT licensed, so you can fork it and run your own marketplace.\n\n${heroImage(registry, 'en')}\n\n[Live website](https://deepseek1024.com/) · [API reference](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/api.md) · [中文目录](../README.md) · [Submit a plugin](../CONTRIBUTING.md) · [Site & CLI source](https://github.com/imsai-sh/dsh-1024store)\n\n[![GitHub Stars](https://img.shields.io/github/stars/imsai-sh/awesome-deepseek-harness-plugins?style=social)](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/stargazers)\n\n## What this project ships\n\n- **Hosted plugin marketplace, one fork away.** [deepseek1024.com](https://deepseek1024.com/) offers search, category filters, install rankings, plugin detail pages, and GitHub activity data on Cloudflare Workers + D1 + KV ([\\`web\\` in dsh-1024store](https://github.com/imsai-sh/dsh-1024store/tree/main/web)). To self-host: fork [dsh-1024store](https://github.com/imsai-sh/dsh-1024store), point \\`routes\\` in \\`web/wrangler.jsonc\\` at your own domain, create the D1 database and KV namespace, set the Worker secrets listed under \\`secrets.required\\`, then run \\`npm run db:migrate:remote\\` and \\`npm run deploy\\` locally — deploys are an explicit local act, not a consequence of pushing (see that repo's [deployment guide](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/deployment.md)).\n- **The marketplace as a \\`dsh\\` plugin.** \\`dsh plugin --profile web add dsh1024@latest\\` installs or upgrades a **1024 Store** entry in Settings and a **1024 Store (count)** tab under Settings → Plugins, with search, filters, installed-state detection, install, and uninstall ([\\`plugin\\` in dsh-1024store](https://github.com/imsai-sh/dsh-1024store/tree/main/plugin)).\n- **Scheduled collection with format validation.** GitHub repositories carrying the \\`dsh-plugin\\` topic are collected automatically and periodically reconciled against the full set. Every candidate is statically validated — the default-branch Git tree, \\`package.json\\`, \\`dsh.bundle.patch\\`, and the patch blob must exist — by reading files only, never installing dependencies or executing repository code ([\\`docs/plugin-discovery.md\\`](../docs/plugin-discovery.md)).\n- **Free query API.** \\`curl 'https://api.deepseek1024.com/v1/plugins/search?q=memory'\\` works anonymously at 50 requests/day (10/minute); a GitHub-login API key raises that to 500/day (30/minute). \\`/api/v1/registry\\` serves a compact, install-ranked snapshot of the catalog (at most 500 entries) — see the [API reference](https://github.com/imsai-sh/dsh-1024store/blob/main/web/docs/api.md).\n\n## Get involved\n\n- **Star** the [repository](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/stargazers) so more DeepSeek Harness users find the catalog.\n- **Open an [issue](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/issues/new)** for wrong plugin metadata, a bad category, or a website/API bug.\n- **Send a [pull request](https://github.com/imsai-sh/awesome-deepseek-harness-plugins/pulls)** — [submit your plugin](../CONTRIBUTING.md) or improve the catalog pipeline; website, CLI, and marketplace-plugin improvements go to [dsh-1024store](https://github.com/imsai-sh/dsh-1024store).\n- **[Fork dsh-1024store](https://github.com/imsai-sh/dsh-1024store/fork)** and run your own marketplace — see the self-hosting steps above.\n\nThe 1024 Store installs plugins from npm only: each plugin's detail page shows the command for its published npm package, and a plugin without one is listed browse-only with its repository link. Install any published plugin and count it on the leaderboard with:\n\n\\`\\`\\`bash\nnpm install -g dsh1024   # once\ndsh1024 plugin --profile web add <npm-package>\n\\`\\`\\`\n\nMonorepo subpackage plugins publish and install their own npm packages, and each sibling is counted on its own. A pull request that adds one new entry is merged automatically once static review passes; one that updates or removes an existing entry passes the same review but waits for maintainer approval. Merged submissions are synced to the website database and into this file automatically; no manual list editing is involved.\n\n## Categories\n\nGroups are collapsed by default. GitHub renders only so much of a single file, so the largest categories list a subset — each summary says how many — while smaller ones are complete. Search the [live website](https://deepseek1024.com/) for the full catalog.\n\n${categoryIndex(groups, 'en')}\n\n${categorySections(prepared, 'en')}\n`\n}\n\nfunction renderReadme(registry, groups, prepared, locale) {\n  return locale === 'zh' ? chineseReadme(registry, groups, prepared) : englishReadme(registry, groups, prepared)\n}\n\nexport async function buildReadmeFiles(registry, categories) {\n  const groups = groupPlugins(registry, categories)\n  const files = {}\n  for (const [locale, relative] of [['zh', 'README.md'], ['en', 'catalog/README.md']]) {\n    files[relative] = renderReadme(registry, groups, fitGroups(registry, groups, locale), locale)\n  }\n  assertRenderable(files)\n  return files\n}\n\nexport function parseArguments(argv) {\n  const options = { root: scriptRoot, base: defaultBase, check: false, help: false }\n  for (let index = 0; index < argv.length; index += 1) {\n    const argument = argv[index]\n    const value = () => {\n      const next = argv[index + 1]\n      if (next === undefined || next.startsWith('--')) throw new Error(`${argument} requires a value`)\n      index += 1\n      return next\n    }\n    if (argument === '--base') options.base = value()\n    else if (argument === '--from-file') options.fromFile = path.resolve(value())\n    else if (argument === '--root') options.root = path.resolve(value())\n    else if (argument === '--check') options.check = true\n    else if (argument === '--help' || argument === '-h') options.help = true\n    else throw new Error(`Unknown argument: ${argument}`)\n  }\n  return options\n}\n\nfunction usage() {\n  return `Usage: npm run readme:build [-- options]\n\nRegenerates README.md (Chinese) and catalog/README.md (English) from the full\nDSH 1024Store catalog: paged GET <base>/api/v2/plugins sweeps, falling back to\nthe uncapped-era <base>/api/v1/registry and then the legacy <base>/plugins.json\nshape when newer endpoints are not deployed yet.\n\nOptions:\n  --base <url>        Catalog API origin (default: ${defaultBase})\n  --from-file <json>  Build from a local registry JSON file instead of the network\n  --root <path>       Repository root for categories.json and output files\n  --check             Verify the committed files are current; do not write\n  --help              Show this help`\n}\n\nasync function main() {\n  const options = parseArguments(process.argv.slice(2))\n  if (options.help) {\n    console.log(usage())\n    return\n  }\n  const categories = await readCategories(options.root)\n  const registry = await loadRegistry(options)\n  assert(\n    registry.plugins.length > 0,\n    'Registry returned 0 plugins; refusing to regenerate README projections from a degenerate snapshot.',\n  )\n  const files = await buildReadmeFiles(registry, categories)\n\n  if (options.check) {\n    const stale = []\n    for (const [relative, content] of Object.entries(files)) {\n      const existing = await readFile(path.join(options.root, relative), 'utf8').catch(() => '')\n      if (existing !== content) stale.push(relative)\n    }\n    if (stale.length > 0) {\n      console.error(`Stale generated files: ${stale.join(', ')}. Run npm run readme:build.`)\n      process.exitCode = 1\n      return\n    }\n    console.log('README projections are up to date.')\n    return\n  }\n\n  for (const [relative, content] of Object.entries(files)) {\n    await writeFile(path.join(options.root, relative), content)\n    console.log(`Wrote ${relative} (${registry.plugins.length} plugins, updated ${registry.updated})`)\n  }\n}\n\nif (process.argv[1] !== undefined && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {\n  try {\n    await main()\n  } catch (error) {\n    console.error(error instanceof Error ? error.message : String(error))\n    process.exitCode = 1\n  }\n}\n"
    },
