      "path": "scripts/sync-catalog.mjs",
      "content": "#!/usr/bin/env node\n\nimport path from 'node:path'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\n\nimport { assert, categoryIdSet, isObject, loadCatalogEntries, readCategories } from './lib/catalog-entry.mjs'\n\nconst scriptRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')\nexport const defaultSyncUrl = 'https://deepseek1024.com/api/v1/catalog/sync'\n\n/**\n * Categories travel to the Worker as data, not as vendored code.\n *\n * catalog/categories.json stays the human source of truth here (submission\n * validation and README generation read it); the sync endpoint reconciles the\n * `catalog_categories` D1 table to exactly the list posted below, so a category\n * change reaches the site through this workflow instead of a coordinated deploy\n * of the dsh-1024store Worker.\n */\n// Mirrors parseSyncCategories in web/worker/app.ts of the dsh-1024store\n// repository — the endpoint rejects the WHOLE sync on any violation, so a\n// malformed categories.json must fail loudly here instead of turning the\n// daily sync red. Keep the two validators aligned by hand (no CI spans the\n// repos): ids /^[a-z][a-z0-9-]{0,39}$/ and unique, `unclassified` reserved,\n// order an integer in [0, 1000000], labels 1..120 chars, list 1..200 items.\nconst CATEGORY_ID = /^[a-z][a-z0-9-]{0,39}$/\n\nfunction syncCategory(category) {\n  assert(isObject(category), 'catalog/categories.json entries must be objects')\n  assert(typeof category.id === 'string' && CATEGORY_ID.test(category.id), `category id ${String(category.id)} must match ${CATEGORY_ID}`)\n  assert(category.id !== 'unclassified', 'the unclassified id is reserved for the synthetic bucket')\n  assert(Number.isInteger(category.order) && category.order >= 0 && category.order <= 1_000_000, `category ${category.id} needs an integer order in [0, 1000000]`)\n  assert(isObject(category.label), `category ${category.id} is missing its label object`)\n  for (const locale of ['en', 'zh']) {\n    assert(typeof category.label[locale] === 'string' && category.label[locale].length > 0 && category.label[locale].length <= 120, `category ${category.id} needs a 1-120 character ${locale} label`)\n  }\n  return { id: category.id, order: category.order, label: { en: category.label.en, zh: category.label.zh } }\n}\n\nexport function buildSyncBody(entries, categories) {\n  const body = { source: 'github_ci' }\n  if (categories !== undefined) {\n    assert(Array.isArray(categories) && categories.length > 0 && categories.length <= 200, 'categories must be a list of 1 to 200 entries')\n    body.categories = categories.map(syncCategory)\n    assert(new Set(body.categories.map(category => category.id)).size === body.categories.length, 'category ids must be unique')\n  }\n  body.entries = entries.map(entry => ({\n    id: entry.id,\n    name: entry.name,\n    repository: entry.repository,\n    category: entry.category,\n    description: {\n      en: entry.description.en,\n      zh: entry.description.zh,\n    },\n    added: entry.added,\n  }))\n  return body\n}\n\nexport function resolveSyncConfig(env, options = {}) {\n  const url = env.CATALOG_SYNC_URL !== undefined && env.CATALOG_SYNC_URL.length > 0\n    ? env.CATALOG_SYNC_URL\n    : defaultSyncUrl\n  if (options.dryRun === true) return { url, token: undefined }\n  const token = env.CATALOG_SYNC_TOKEN\n  if (typeof token !== 'string' || token.trim().length === 0) {\n    throw new Error('CATALOG_SYNC_TOKEN is not set. Configure the repository secret (or export the variable) before running catalog:sync, or pass --dry-run to preview the request body.')\n  }\n  return { url, token: token.trim() }\n}\n\nexport async function postCatalogSync({ url, token, body, fetchImplementation = globalThis.fetch }) {\n  assert(typeof fetchImplementation === 'function', 'A fetch implementation is required')\n  const response = await fetchImplementation(url, {\n    method: 'POST',\n    headers: {\n      Authorization: `Bearer ${token}`,\n      'Content-Type': 'application/json',\n      'User-Agent': 'dsh-1024store-catalog-sync',\n    },\n    body: JSON.stringify(body),\n  })\n  const detail = await response.text()\n  if (!response.ok) {\n    throw new Error(`Catalog sync failed: HTTP ${response.status} for ${url}: ${detail.slice(0, 500)}`)\n  }\n  let result\n  try {\n    result = JSON.parse(detail)\n  } catch {\n    throw new Error(`Catalog sync returned a non-JSON response: ${detail.slice(0, 200)}`)\n  }\n  if (result?.ok !== true) {\n    throw new Error(`Catalog sync was not acknowledged: ${detail.slice(0, 500)}`)\n  }\n  return result\n}\n\nexport function parseArguments(argv) {\n  const options = { root: scriptRoot, dryRun: false, help: false }\n  for (let index = 0; index < argv.length; index += 1) {\n    const argument = argv[index]\n    if (argument === '--dry-run') options.dryRun = true\n    else if (argument === '--help' || argument === '-h') options.help = true\n    else if (argument === '--root') {\n      const next = argv[index + 1]\n      if (next === undefined || next.startsWith('--')) throw new Error('--root requires a value')\n      options.root = path.resolve(next)\n      index += 1\n    } else throw new Error(`Unknown argument: ${argument}`)\n  }\n  return options\n}\n\nfunction usage() {\n  return `Usage: npm run catalog:sync [-- options]\n\nPushes every catalog/plugins/*.json entry plus the ordered catalog/categories.json\nlist to POST /api/v1/catalog/sync so the production D1 catalog stays the single\nsource of truth. The endpoint reconciles its category table to exactly the posted\nlist, so category changes need no Worker redeploy.\n\nOptions:\n  --dry-run       Validate the payload and print the request body without sending it\n  --root <path>   Repository root containing catalog/ (default: this repository)\n  --help          Show this help\n\nEnvironment:\n  CATALOG_SYNC_URL     Sync endpoint (default: ${defaultSyncUrl})\n  CATALOG_SYNC_TOKEN   Bearer token; required unless --dry-run`\n}\n\nasync function main() {\n  const options = parseArguments(process.argv.slice(2))\n  if (options.help) {\n    console.log(usage())\n    return\n  }\n  const categories = await readCategories(options.root)\n  const entries = await loadCatalogEntries(options.root, categoryIdSet(categories))\n  const body = buildSyncBody(entries, categories)\n  if (options.dryRun) {\n    process.stdout.write(`${JSON.stringify(body, null, 2)}\\n`)\n    console.error(`Dry run: validated ${entries.length} entries and ${categories.length} categories; nothing was sent.`)\n    return\n  }\n  const { url, token } = resolveSyncConfig(process.env)\n  const result = await postCatalogSync({ url, token, body })\n  const acknowledgedCategories = result.categories === undefined ? '' : `, categories=${result.categories}`\n  console.log(`Synced ${entries.length} catalog entries and ${categories.length} categories to ${url}: total=${result.total ?? 'unknown'}${acknowledgedCategories}, removedSources=${result.removedSources ?? 'unknown'}`)\n}\n\nif (process.argv[1] !== undefined && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {\n  try {\n    await main()\n  } catch (error) {\n    console.error(error instanceof Error ? error.message : String(error))\n    process.exitCode = 1\n  }\n}\n"
    },
    {
      "path": "skills/submit-dsh-plugin/SKILL.md",
      "content": "---\nname: submit-dsh-plugin\ndescription: 验证并提交 DeepSeek Harness 插件到 imsai-sh/awesome-deepseek-harness-plugins 社区目录。适用于插件作者要求收录、发布或提交自己的插件，创建目录 JSON，修复目录提交 PR，或者发起合规 PR。检查公开仓库、dsh-plugin topic、dsh.bundle.patch、作者测试证据、双语元数据和单文件差异，并在获得授权后执行 fork、push 和创建 PR。\n---\n\n# 提交 DSH 插件\n\n从插件作者的仓库准备一份聚焦的目录收录 PR。始终把 `catalog/plugins/*.json` 视为贡献者唯一可以编辑的目录源数据。\n\n## 安全与范围\n\n- 不得在插件提交 PR 中编辑 `README.md`、`catalog/README.md`、工作流或脚本。两个 README 是 bot 生成的目录投影，合并后由 CI 自动刷新。\n- 不得仅为了检查插件而安装依赖、运行生命周期脚本、构建或执行插件代码。运行作者代码前必须先征得同意。\n- 保留所有无关的本地改动。如果目录仓库工作区不干净，应停止操作；除非用户指定一个干净 worktree，或明确界定现有改动的范围。\n- 将“准备”或“起草”理解为仅做本地修改。只有用户明确要求“提交”“推送”或“创建 PR”时，才视为已授权在展示准确目标后执行 fork、push 和创建 PR。\n- 不得手动合并 PR，也不得修改生成投影。合规的非草稿新增类目录 PR 会在可信静态审查通过后自动合并；修改或删除既有条目的 PR 即使静态审查通过也不会自动合并，必须等待目录仓库维护者人工审核后手动合并。合并进入 `main` 后，CI 自动把目录条目同步到网站数据库（D1）并重新生成两个 README，即自动同步，无任何维护者手工步骤。\n\n## 1. 明确提交信息\n\n确定以下内容：\n\n- 插件 ID：仓库级插件为 `owner/repository`；monorepo 子包插件为 `owner/repository/sub/dir`，前两段之后的路径段指向仓库内的子目录\n- 插件名称：仓库级插件通常与仓库名一致，子目录 ID 默认取最后一个路径段（子包目录名）\n- 一个主要目录分类\n- 客观的英文与中文简介\n- 作者实际执行的测试命令和结果\n\nID 各段仅限 `A-Za-z0-9_.-` 字符，路径段不得是 `.` 或 `..`，总长不超过 201 字符。无论 ID 是否携带路径，条目的 `repository` 字段始终是由前两段推导的仓库根 URL `https://github.com/owner/repository`。ID 的路径段锁定插件源码位置：子目录 ID 的 `<sub/dir>/package.json` 必须恰好是插件的 manifest。安装入口只来自发布到 npm 的包（1024 Store 仅提供 npm 安装），目录条目本身只记录源码仓库。\n\n目录仓库固定使用 `https://github.com/imsai-sh/awesome-deepseek-harness-plugins`。创建文件前，读取其当前 checkout 中的 `CONTRIBUTING.md` 和 `catalog/categories.json`；如果线上仓库规范与本 Skill 不同，以线上规范为准。\n\n选择分类或编写 PR 时，读取 [references/submission-reference.md](references/submission-reference.md)。\n\n## 2. 检查插件仓库\n\n先完成只读检查：\n\n1. 确认仓库公开且存在默认分支。\n2. 确认仓库包含 `dsh-plugin` GitHub topic。如果缺少 topic、用户拥有该仓库且已授权外部写入，才可执行 `gh repo edit owner/repository --add-topic dsh-plugin`。topic 作用于仓库本身：`gh repo edit` 的参数只取 ID 的前两段 `owner/repository`，子目录 ID 的路径段不参与。\n3. 定位插件的 manifest：两段 ID 可使用根目录或任意嵌套的 `package.json`（排除 `node_modules`）；子目录 ID 则必须在 `<sub/dir>/package.json` 恰好找到 manifest——ID 的路径就是插件在仓库中的位置，仓库里其他位置的 manifest 不算数。\n4. 确认其中声明了非空字符串 `dsh.bundle.patch`。\n5. 相对于声明该字段的 `package.json` 解析补丁路径；拒绝绝对路径、反斜杠以及跳出仓库的路径。\n6. 确认 manifest 和引用的补丁都存在于 GitHub 默认分支，而不只是尚未推送的本地提交。\n7. 向作者说明**安装可用性**：1024 Store 只提供 npm 安装，不再提供 GitHub 源码安装。\n   网站会自动探测 manifest 中声明的 npm 包名；只要 npm 上的 latest manifest 声明 `dsh.bundle`，插件即可安装（`repository` 回链缺失或不一致不影响验证）。\n   **未发布 npm 包不影响收录**：插件照常收录，以浏览模式展示（有仓库链接，无安装命令），PR 评论会提示作者发布 npm 包后目录自动检测、无需追加 PR。\n8. 记录作者实际执行的兼容性测试。如果尚未测试，应停止并要求作者先测试；目录自动审查不会执行第三方代码。\n\n使用 GitHub 或 `gh` 获取远程默认分支证据。不得用仅存在于本地的文件作为证明。\n\n## 3. 准备干净的目录分支\n\n优先复用干净的目录 checkout。仅本地准备时，直接克隆上游目录仓库，不创建 fork。已授权正式提交时，使用 GitHub CLI fork 并克隆，或者把用户已有的 fork 添加为推送 remote。保留上游仓库 remote，拉取其默认分支，然后基于完整插件 ID 创建聚焦分支，例如：\n\n```text\nadd-owner-repository\nadd-owner-repository-sub-dir\n```\n\n子目录 ID 的分支名包含 slug 化的路径段，这样同一仓库的两个子包提交不会撞到同一个分支名。\n\n不得把目录条目放进插件仓库。不得基于另一个尚未合并的贡献分支创建本次分支。\n\n## 4. 创建目录条目\n\n解析本 Skill 目录的绝对路径，然后运行其中的确定性创建脚本：\n\n```bash\nnode <skill-directory>/scripts/create-catalog-entry.mjs \\\n  --catalog-root <catalog-checkout> \\\n  --id owner/repository \\\n  --category skill \\\n  --description-en \"A factual English description.\" \\\n  --description-zh \"客观、具体的中文说明。\"\n```\n\nmonorepo 子包传入完整 ID，例如 `--id owner/repository/packages/foo`；脚本会保持 `repository` 为仓库根 URL，并把路径段编入文件名。\n\n仅当展示名称需要不同于默认值（两段 ID 为仓库名，子目录 ID 为最后一个路径段）时传入 `--name`。仅当需要覆盖当天 UTC 日期时传入 `--added YYYY-MM-DD`。\n\n脚本必须拒绝未知分类、重复 ID（不区分大小写，含路径段）、无效 ID 和已存在的目标文件。同一仓库以不同子目录路径提交多个条目是允许的，只要每个完整 ID 唯一。不得绕过这些错误手工创建文件。\n\n## 5. 验证单文件约束\n\n要求当前分支相对上游最新默认分支的完整差异只包含一个新增文件：\n\n```text\nA catalog/plugins/<owner>--<repository>.json\n```\n\n文件名由完整 ID 推导：每个 `/` 分隔的段转为全小写、把连续非字母数字字符替换成 `-`，再用 `--` 连接。子目录 ID 的路径段同样编入文件名，例如 `owner/repository/packages/foo` → `A catalog/plugins/owner--repository--packages--foo.json`。文件始终平铺在 `catalog/plugins/` 下，不创建子目录。\n\n然后执行以下检查：\n\n1. 再次解析 JSON。\n2. 确认文件名与规范化后的 `id` 一致。\n3. 确认中英文简介客观、中性、具体，且有仓库证据支持。\n4. 确认 `added` 是提交日期。\n5. 只暂存该 JSON 文件，并运行 `git diff --cached --check`。\n6. 检查暂存差异是否包含凭据、私有路径、邮箱、token 或无关数据。\n\n如果可以针对已提交分支在本地运行目录仓库的可信审查脚本，应传入上游基础 SHA、当前分支 HEAD SHA、作为 `PLUGIN_REVIEW_ROOT` 的目录 checkout，以及已认证的 GitHub token。不得把该静态审查描述成插件运行测试。\n\n## 6. 提交并创建 PR\n\n使用聚焦的提交信息，写入完整插件 ID，例如：\n\n```text\ncatalog: add owner/repository\ncatalog: add owner/repository/packages/foo\n```\n\n推送前，说明 fork、分支、上游仓库和唯一暂存的文件。只有获得授权后才可推送并创建 PR。\n\n使用 [references/submission-reference.md](references/submission-reference.md) 中的模板编写 PR，填写真实的测试命令和结果，并保持“允许维护者修改”开启。\n仓库根 PR 模板只包含插件与目录提交确认清单，逐项如实完成即可。\n\n## 7. 跟进自动检查\n\n创建 PR 后：\n\n1. 返回 PR URL。\n2. 检查 `Plugin submission review / static-review` 及其机器人评论。\n3. 如果检查失败，PR 会保持打开且不会被工作流自动关闭；仅通过修改目录 JSON 修复。不得为了通过检查而加入 README 或其他生成投影。\n4. 非草稿新增类 PR 检查通过后会自动 squash merge，GitHub 随后将其记录为已合并（因此不再保持打开）；草稿 PR 会在标记 ready for review 后重新检查并自动合并。\n5. 修改或删除既有条目的 PR 检查通过后，机器人会评论说明需要维护者人工审核；此时无须任何贡献者操作，等待维护者手动合并即可，不要催促或自行合并。\n6. 不要请求维护者批准 fork CI，也不要手动合并；目录 PR 不运行贡献者分支上的通用 CI。\n\n静态审查通过即表示该目录元数据符合收录规则；新增类 PR 随之触发自动合并，修改/删除类 PR 则进入维护者人工审核。合并进入 `main` 后，catalog-sync 工作流会自动把条目同步到线上目录数据库并刷新 `README.md` 与 `catalog/README.md`（github-actions[bot] 提交），插件随即出现在 [deepseek1024.com](https://deepseek1024.com/) 与两个 README 目录中。该结果仍不代表对第三方插件行为、安全性或质量的背书。\n\n## 已存在的条目与更新\n\n如果完整插件 ID 已经存在（不区分大小写），不得创建重复条目。唯一性按完整 ID 判断：同一仓库已存在其他条目（例如仓库级条目或另一个子目录条目）并不阻止提交一个新的、不同的 ID。需要修正或下架既有条目时，可以提交只修改或删除对应 `catalog/plugins/*.json` 文件的 PR：静态审查照常运行并逐个校验修改后的条目，但此类 PR 不会自动合并，必须由维护者人工审核后手动合并。提交前应向用户说明这一等待环节。\n"
    },
    {
      "path": "skills/submit-dsh-plugin/scripts/create-catalog-entry.mjs",
      "content": "#!/usr/bin/env node\n\nimport { mkdir, readFile, readdir, writeFile } from 'node:fs/promises'\nimport path from 'node:path'\nimport process from 'node:process'\n\nconst allowedOptions = new Set([\n  'catalog-root',\n  'id',\n  'name',\n  'category',\n  'description-en',\n  'description-zh',\n  'added',\n])\n\nfunction usage() {\n  return `用法：\n  node create-catalog-entry.mjs \\\\\n    --catalog-root <path> \\\\\n    --id <owner/repository[/sub/dir]> \\\\\n    --category <category-id> \\\\\n    --description-en <text> \\\\\n    --description-zh <text> \\\\\n    [--name <display-name>] \\\\\n    [--added <YYYY-MM-DD>] \\\\\n    [--dry-run]\n\nmonorepo 子包在 --id 中追加仓库内路径段（例如 owner/repository/packages/foo），\n路径段锁定插件 manifest 的位置（<sub/dir>/package.json）。`\n}\n\nfunction fail(message) {\n  throw new Error(message)\n}\n\nfunction parseArgs(argv) {\n  const values = new Map()\n  let dryRun = false\n  for (let index = 0; index < argv.length; index += 1) {\n    const argument = argv[index]\n    if (argument === '--help' || argument === '-h') return { help: true, values, dryRun }\n    if (argument === '--dry-run') {\n      dryRun = true\n      continue\n    }\n    if (!argument.startsWith('--')) fail(`意外参数：${argument}`)\n    const key = argument.slice(2)\n    if (!allowedOptions.has(key)) fail(`未知选项：--${key}`)\n    if (values.has(key)) fail(`重复选项：--${key}`)\n    const value = argv[index + 1]\n    if (value === undefined || value.startsWith('--')) fail(`--${key} 缺少参数值`)\n    values.set(key, value)\n    index += 1\n  }\n  return { help: false, values, dryRun }\n}\n\nfunction required(values, key) {\n  const value = values.get(key)?.trim()\n  if (!value) fail(`缺少必填选项：--${key}`)\n  return value\n}\n\nfunction slugPart(value) {\n  return value\n    .toLocaleLowerCase('en-US')\n    .replace(/[^a-z0-9]+/g, '-')\n    .replace(/^-+|-+$/g, '')\n}\n\n// 文件名覆盖完整 ID：每个 `/` 分隔的段转小写并把连续非字母数字字符替换成\n// `-`，再用 `--` 连接（与目录仓库 scripts/lib/catalog-entry.mjs 的\n// pluginFileName 保持一致），因此同一仓库的不同子目录条目得到不同文件名。\nfunction pluginFileName(id) {\n  return `${id.split('/').map(slugPart).join('--')}.json`\n}\n\n// 插件 ID 为 owner/repository，可追加仓库内路径段（monorepo 子包）。路径段\n// 锁定插件 manifest 在仓库中的目录并与 git 树路径逐段比对，因此 `.` 与 `..`\n// 段一律拒绝；201 字符上限与目录仓库的可信审查保持一致。\nconst idSegmentPattern = /^[A-Za-z0-9_.-]+$/\n\nfunction isValidPluginId(id) {\n  if (id.length > 201) return false\n  const segments = id.split('/')\n  return segments.length >= 2\n    && segments.every(segment => idSegmentPattern.test(segment) && segment !== '.' && segment !== '..')\n}\n\nfunction isIsoDate(value) {\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return false\n  const parsed = new Date(`${value}T00:00:00.000Z`)\n  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value\n}\n\nasync function readJson(file) {\n  try {\n    return JSON.parse(await readFile(file, 'utf8'))\n  } catch (error) {\n    fail(`无法读取 ${file}：${error instanceof Error ? error.message : String(error)}`)\n  }\n}\n\nfunction validateDescription(value, locale) {\n  const description = value.trim()\n  if (description.length === 0 || description.length > 1000) {\n    fail(`${locale}简介长度必须为 1–1000 个字符`)\n  }\n  return description\n}\n\nasync function main() {\n  const { help, values, dryRun } = parseArgs(process.argv.slice(2))\n  if (help) {\n    console.log(usage())\n    return\n  }\n\n  const root = path.resolve(required(values, 'catalog-root'))\n  const id = required(values, 'id')\n  if (!isValidPluginId(id)) {\n    fail('--id 必须使用 owner/repository[/sub/dir] 格式（各段仅限 A-Za-z0-9_.-，路径段不能是 . 或 ..，总长不超过 201 字符）')\n  }\n  const idSegments = id.split('/')\n  const [owner, repositoryName] = idSegments\n  // 默认展示名称取 ID 的最后一段：两段 ID 即仓库名，子目录 ID 即子包目录名。\n  const name = (values.get('name') ?? idSegments.at(-1)).trim()\n  if (name.length === 0 || name.length > 120) fail('--name 长度必须为 1–120 个字符')\n\n  const categoriesFile = path.join(root, 'catalog/categories.json')\n  const pluginsDirectory = path.join(root, 'catalog/plugins')\n  const categories = await readJson(categoriesFile)\n  const categoryIds = new Set(categories?.categories?.map(category => category?.id))\n  const category = required(values, 'category')\n  if (!categoryIds.has(category)) {\n    fail(`未知分类“${category}”。可用分类：${[...categoryIds].join(', ')}`)\n  }\n\n  const added = (values.get('added') ?? new Date().toISOString().slice(0, 10)).trim()\n  if (!isIsoDate(added)) fail('--added 必须是 YYYY-MM-DD 格式的有效日期')\n\n  const entry = {\n    $schema: '../schema/plugin.schema.json',\n    id,\n    name,\n    // repository 始终是由 ID 前两段推导的仓库根 URL；子目录路径只存在于 id 中。\n    repository: `https://github.com/${owner}/${repositoryName}`,\n    category,\n    description: {\n      en: validateDescription(required(values, 'description-en'), '英文'),\n      zh: validateDescription(required(values, 'description-zh'), '中文'),\n    },\n    added,\n  }\n\n  let existingFiles\n  try {\n    existingFiles = (await readdir(pluginsDirectory)).filter(file => file.endsWith('.json'))\n  } catch (error) {\n    fail(`无法读取 ${pluginsDirectory}：${error instanceof Error ? error.message : String(error)}`)\n  }\n  // 唯一性按完整 ID（不区分大小写）判断：同一仓库允许以不同子目录路径\n  // 出现在多个条目中，因此不做仓库级别的重复拦截。\n  for (const file of existingFiles) {\n    const existing = await readJson(path.join(pluginsDirectory, file))\n    if (existing?.id?.toLocaleLowerCase('en-US') === id.toLocaleLowerCase('en-US')) {\n      fail(`插件 ID 已存在于 catalog/plugins/${file}`)\n    }\n  }\n\n  const relativeTarget = path.posix.join('catalog/plugins', pluginFileName(id))\n  const target = path.join(root, relativeTarget)\n  const serialized = `${JSON.stringify(entry, null, 2)}\\n`\n  if (dryRun) {\n    console.log(serialized.trimEnd())\n    console.error(`试运行：将创建 ${relativeTarget}`)\n    return\n  }\n\n  await mkdir(pluginsDirectory, { recursive: true })\n  try {\n    await writeFile(target, serialized, { flag: 'wx' })\n  } catch (error) {\n    if (error?.code === 'EEXIST') fail(`拒绝覆盖 ${relativeTarget}`)\n    throw error\n  }\n  console.log(`已创建 ${relativeTarget}`)\n}\n\nmain().catch(error => {\n  console.error(`错误：${error instanceof Error ? error.message : String(error)}`)\n  console.error(usage())\n  process.exitCode = 1\n})\n"
    }
  ],
